// ==== Fill in once: Google Drive file IDs of payments.json and reviews.json ====
const FILE_IDS = {
  payments: 'PASTE_DRIVE_FILE_ID_OF_payments.json',
  reviews: 'PASTE_DRIVE_FILE_ID_OF_reviews.json',
};
// ===============================================================================
const source = $input.first().json.query.source;
if (!FILE_IDS[source]) {
  throw new Error(`Unknown source "${source}". Use ?source=payments or ?source=reviews`);
}
return [{ json: { source, file_id: FILE_IDS[source] } }];

// Return one page, like a real paginated API: ?source=payments&page=2&page_size=20000
const query = $('Webhook').first().json.query;
const source = $('Pick file').first().json.source;
const page = Math.max(1, parseInt(query.page ?? '1', 10) || 1);
const pageSize = Math.min(Math.max(parseInt(query.page_size ?? '20000', 10) || 20000, 1), 50000);
const records = $input.first().json.data[source] ?? [];
const totalPages = Math.max(1, Math.ceil(records.length / pageSize));
return [{ json: {
  source,
  page,
  page_size: pageSize,
  total_pages: totalPages,
  total: records.length,
  data: records.slice((page - 1) * pageSize, page * pageSize),
} }];
